def eval_rpn(tokens):
    s = []
    ops = {'+', '-', '*', '/'}
    for t in tokens:
        if t in ops:
            b, a = s.pop(), s.pop()
            if t == '+': s.append(a + b)
            elif t == '-': s.append(a - b)
            elif t == '*': s.append(a * b)
            else: s.append(int(a / b))
        else:
            s.append(int(t))
    return s[0]
```

